INSERT INTO public.site_pages (slug, title, content, draft_content, seo_description, is_published, published_at)
VALUES (
  'fuer-veranstalter-neu',
  'Für Veranstalter',
  '{"content":[{"type":"Seitenkopf","props":{"id":"Seitenkopf-f85748f4","ueberschrift":"Wir zeigen Geschichte zum Anfassen","text":"<p>Wir sind ein Wiesbadener Verein, der Alltag, Handwerk und Militärgeschichte des Nassauer Landes zeigt, vom Mittelalter über die Napoleonik bis zum Ersten Weltkrieg. Dabei arbeiten wir mit Partnern zusammen, die historische Bildung und Authentizität in den Mittelpunkt stellen.</p>","ausrichtung":"mitte","hintergrund":"karte","flaeche":"voll","breite":"schmal","textfarbe":"standard","abstandOben":"gross","abstandUnten":"gross"}},{"type":"Textabschnitt","props":{"id":"Textabschnitt-def1a922","inhalt":"<h2>Was wir bieten</h2><p>Im Mittelpunkt unserer Auftritte stehen Displayarbeit und Wissensvermittlung. Wir präsentieren rekonstruierte Alltagsgegenstände, Kleidung, Ausrüstung und Handwerk und erklären den historischen Kontext fundiert und verständlich für jedes Publikum.</p><p>Wir verstehen uns dabei nicht als Kulisse, sondern als Gesprächspartner. Besucher können Fragen stellen, Objekte aus der Nähe betrachten und mit uns über Geschichte ins Gespräch kommen.</p><p>Viele unserer Ausrüstungsgegenstände und Kleidungsstücke entstehen in eigener Arbeit innerhalb der Gruppe – orientiert an Museumsfunden, zeitgenössischen Abbildungen und aktuellem Forschungsstand.</p><p>Wir treten gegen eine Aufwandsentschädigung auf, über deren Höhe wir uns gerne im Rahmen der Anfrage abstimmen.</p>","breite":"schmal","ausrichtung":"links","aufzaehlung":"punkte","abstandOben":"klein","abstandUnten":"keiner","textfarbe":"standard","hintergrund":"keine","flaeche":"inhalt"}},{"type":"Einzelbild","props":{"id":"Einzelbild-22cda0a7","bildSchluessel":"lederworkshop-veranstalter","bildunterschrift":"","bildbreite":"schmal","breite":"schmal","abstandOben":"klein","abstandUnten":"klein"}},{"type":"Textabschnitt","props":{"id":"Textabschnitt-a0ab1d8a","inhalt":"<h2>Unsere Darstellungen</h2><p>Aktuell decken wir drei Epochen der regionalen Geschichte ab:</p><ul><li><strong>Spätmittelalter (1290–1310)</strong><br>Grafschaft Nassau im Raum Wiesbaden – vom Niederadel bis zum Handwerk</li><li><strong>Napoleonische Kriege (1815)</strong><br>Nassauische Grenadiere des 1. Linien-Regiments</li><li><strong>Erster Weltkrieg (1916/17)</strong><br>1. Nassauisches Pionier-Bataillon Nr. 21</li></ul>","breite":"schmal","ausrichtung":"links","aufzaehlung":"schlicht","abstandOben":"klein","abstandUnten":"klein","textfarbe":"standard","hintergrund":"keine","flaeche":"inhalt"}},{"type":"Einzelbild","props":{"id":"Einzelbild-fa4aa0e2","bildSchluessel":"epochen-uebersicht-veranstalter","bildunterschrift":"","bildbreite":"voll","breite":"schmal","abstandOben":"klein","abstandUnten":"klein"}},{"type":"Textabschnitt","props":{"id":"Textabschnitt-9978df4a","inhalt":"<h2>Mit wem wir arbeiten</h2><p>Unsere Partner sind Städte, Museen, historische Orte wie Burgen und Klöster sowie Veranstaltungen mit dokumentarisch-historischem Anspruch.</p><p>Als Wiesbadener Verein liegt unser geografischer Schwerpunkt auf dem Raum Wiesbaden und dem historischen Nassauer Land – dem Gebiet, das heute grob den Rheingau-Taunus-Kreis, den Lahn-Dill-Kreis und angrenzende Regionen umfasst. Unsere Mitglieder sind jedoch deutschlandweit verteilt, und wir sind grundsätzlich auch überregional für Veranstaltungen verfügbar.</p><p>Dieser regionale Fokus spiegelt sich auch in unseren Darstellungen wider: Wir beschäftigen uns bewusst mit der Geschichte dieser Region und den Menschen, die hier gelebt haben.</p>","breite":"schmal","ausrichtung":"links","aufzaehlung":"punkte","abstandOben":"klein","abstandUnten":"klein","textfarbe":"standard","hintergrund":"keine","flaeche":"inhalt"}},{"type":"Hinweiskasten","props":{"id":"Hinweiskasten-39137263","stil":"notiz","ebene":"h2","symbol":"keins","ueberschrift":"Unser Schwerpunkt","inhalt":"<p>Unser Angebot richtet sich vor allem an Veranstalter, die historischen Inhalt und Vermittlung in den Mittelpunkt stellen.</p><p>Formate, die vor allem auf Unterhaltung oder Fantasy setzen, passen daher in der Regel weniger zu unserer Arbeit.</p>","knopf":"","ziel":"","betont":false,"breite":"schmal","abstandOben":"klein","abstandUnten":"klein"}},{"type":"Veranstalteranfrage","props":{"id":"Veranstalteranfrage-0756dd88","ueberschrift":"Anfrage","hinweis":"<p>Sie möchten uns für eine Veranstaltung anfragen? Wir freuen uns darüber.</p><p>Je mehr Informationen Sie uns bereits zu Termin, Ort und Art der Veranstaltung geben können, desto besser können wir einschätzen, ob und wie wir zusammenpassen.</p>","breite":"schmal","abstandOben":"klein","abstandUnten":"keiner"}},{"type":"Darstellungen","props":{"id":"Darstellungen-921d4e46","kategorie":"","ueberschrift":"Unsere Darstellungen","einleitung":"Welche Epochen und Handwerke wir zeigen können – nach Zeitstellung geordnet. Sprechen Sie uns gern an, wenn Sie etwas Bestimmtes suchen.","breite":"breit","abstandOben":"weit","abstandUnten":"weit"}}],"root":{"props":{"title":"Für Veranstalter"}}}'::jsonb,
  '{"content":[{"type":"Seitenkopf","props":{"id":"Seitenkopf-f85748f4","ueberschrift":"Wir zeigen Geschichte zum Anfassen","text":"<p>Wir sind ein Wiesbadener Verein, der Alltag, Handwerk und Militärgeschichte des Nassauer Landes zeigt, vom Mittelalter über die Napoleonik bis zum Ersten Weltkrieg. Dabei arbeiten wir mit Partnern zusammen, die historische Bildung und Authentizität in den Mittelpunkt stellen.</p>","ausrichtung":"mitte","hintergrund":"karte","flaeche":"voll","breite":"schmal","textfarbe":"standard","abstandOben":"gross","abstandUnten":"gross"}},{"type":"Textabschnitt","props":{"id":"Textabschnitt-def1a922","inhalt":"<h2>Was wir bieten</h2><p>Im Mittelpunkt unserer Auftritte stehen Displayarbeit und Wissensvermittlung. Wir präsentieren rekonstruierte Alltagsgegenstände, Kleidung, Ausrüstung und Handwerk und erklären den historischen Kontext fundiert und verständlich für jedes Publikum.</p><p>Wir verstehen uns dabei nicht als Kulisse, sondern als Gesprächspartner. Besucher können Fragen stellen, Objekte aus der Nähe betrachten und mit uns über Geschichte ins Gespräch kommen.</p><p>Viele unserer Ausrüstungsgegenstände und Kleidungsstücke entstehen in eigener Arbeit innerhalb der Gruppe – orientiert an Museumsfunden, zeitgenössischen Abbildungen und aktuellem Forschungsstand.</p><p>Wir treten gegen eine Aufwandsentschädigung auf, über deren Höhe wir uns gerne im Rahmen der Anfrage abstimmen.</p>","breite":"schmal","ausrichtung":"links","aufzaehlung":"punkte","abstandOben":"klein","abstandUnten":"keiner","textfarbe":"standard","hintergrund":"keine","flaeche":"inhalt"}},{"type":"Einzelbild","props":{"id":"Einzelbild-22cda0a7","bildSchluessel":"lederworkshop-veranstalter","bildunterschrift":"","bildbreite":"schmal","breite":"schmal","abstandOben":"klein","abstandUnten":"klein"}},{"type":"Textabschnitt","props":{"id":"Textabschnitt-a0ab1d8a","inhalt":"<h2>Unsere Darstellungen</h2><p>Aktuell decken wir drei Epochen der regionalen Geschichte ab:</p><ul><li><str